import fs from "node:fs";const read=p=>fs.readFileSync(p,"utf8"),reg=read("js/puzzle-registry.js"),core=read("js/core.js"),fb=read("js/firebase.js"),rules=read("firestore.rules"),index=read("index.html"),tutorial=read("js/tutorials.js"),must=(ok,msg)=>{if(!ok)throw new Error(msg)};must(/bin:\{[^\n]*tutorial:\{version:1/.test(reg),"Binair tutorialmetadata ontbreekt");must((reg.match(/title:"/g)||[]).length>=5,"Binair tutorial heeft te weinig stappen");must(core.includes('new CustomEvent("pdpuzzleloaded"'),"core publiceert geen puzzel-load event");must(index.includes('js/tutorials.js?v=186'),"tutorial-engine wordt niet geladen");must(tutorial.includes("data-tutorial-skip")&&tutorial.includes("Uitleg stap voor stap"),"skip/restart ontbreekt");must(tutorial.includes('remember(t,"completed")')&&tutorial.includes('remember(t,"skipped")'),"persoonlijke tutorialstatus ontbreekt");must(fb.includes('tutorials:legacy?{bin:"skipped"}:{}'),"legacy-default ontbreekt");must(fb.includes("setTutorialState:async"),"Firebase tutorialstatus API ontbreekt");must(rules.includes("'favoritePuzzleTypes','dailyDifficulty','tutorials'"),"rules staan tutorialstatus niet toe");console.log("Fase 9 tutorialpilot: OK");
